WITH filtered AS (SELECT id, full_name, email, manager_id, job_title, salary, is_remote, level, COALESCE(email, 'N/A') AS email_filled, CONCAT_WS('-', level, job_title) AS level_job_title_key, COALESCE(job_title, 'DIRECT') AS job_title_clean FROM employees WHERE dept_id IN (2, 10)) SELECT *, ROUND(salary / SUM(salary) OVER (PARTITION BY manager_id, job_title), 4) AS salary_share, LAG(salary, 2) OVER (PARTITION BY level, job_title ORDER BY salary, id) AS prev_salary, CUME_DIST() OVER w_ordered AS salary_cume_dist, STDDEV_SAMP(salary) OVER (PARTITION BY job_title, level) AS job_title_stddev_samp_salary FROM filtered WINDOW w_ordered AS (PARTITION BY level ORDER BY salary DESC);
